const ACHIEVEMENTS={"primer_quiz":{"icon":"🧠","label":"Primer quiz del presupuesto superado"},"flash_master":{"icon":"🃏","label":"Todos los términos del costo explorados"},"clasif_pro":{"icon":"🗂️","label":"Clasificador de costo fijo y variable experto"},"id_master":{"icon":"🔍","label":"Identificador de piezas del presupuesto maestro"},"reto_hero":{"icon":"🏆","label":"Héroe del reto de los 30 segundos"},"sopa_champ":{"icon":"🔤","label":"Campeón de la sopa del presupuesto"},"eval_ace":{"icon":"🎓","label":"Evaluación final aprobada con honores"},"full_xp":{"icon":"👑","label":"Etapa 2 de la Ruta del Poder completada"}};
