const enfermedadData=[{"disease":"El taller dejó 2.400 lempiras y quedó la sensación de haber perdido","characteristic":"No se contaron las horas de preparar y de dar el taller","opts":["No se contaron las horas de preparar y de dar el taller","El precio por maestro era muy bajo","Fueron pocos participantes","El refrigerio salió caro"]},{"disease":"Las treinta fichas «gratis» se llevaron la tarde entera","characteristic":"Se calculó papel y tinta pero no el viaje ni la revisión","opts":["Se calculó papel y tinta pero no el viaje ni la revisión","La impresora era lenta","El papel estaba caro ese mes","Se imprimieron de más"]},{"disease":"Cinco aulas pagando y el mes seguía saliendo del bolsillo de la casa","characteristic":"El equilibrio no eran cinco: el soporte por aula bajaba el margen","opts":["El equilibrio no eran cinco: el soporte por aula bajaba el margen","Las aulas pagaron tarde","Los fijos subieron ese mes","Se cobró muy poco por aula"]},{"disease":"Llegó la factura del hospedaje y no había con qué","characteristic":"Lo gratis no estaba anotado con su precio de mercado","opts":["Lo gratis no estaba anotado con su precio de mercado","El proveedor subió los precios sin avisar","Se gastó de más en impresión","Faltaron aulas ese mes"]},{"disease":"Se compró equipo y en marzo no alcanzó para el dominio","characteristic":"Se sacó del sobre de fijos para reinvertir","opts":["Se sacó del sobre de fijos para reinvertir","El equipo salió más caro de lo previsto","Bajaron los ingresos","El dominio subió de precio"]},{"disease":"Los anuncios en el APK dieron menos que el dominio de un mes","characteristic":"No se calculó cuánto entraba de verdad con el tráfico actual","opts":["No se calculó cuánto entraba de verdad con el tráfico actual","Los anuncios estaban mal colocados","La aplicación tenía errores","Faltó publicidad del proyecto"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

