const identifyTaskDB=[{"s":"Se paga aunque no se atienda ninguna aula.","type":"Costo fijo"},{"s":"Sube con cada ficha impresa.","type":"Costo variable"},{"s":"El precio del propio tiempo, aunque no lo pague nadie.","type":"Costo de la hora"},{"s":"Lo que se deja de hacer por hacer otra cosa.","type":"Costo de oportunidad"},{"s":"Precio menos costo por unidad.","type":"Margen"},{"s":"Cuántas unidades hacen falta para no perder.","type":"Punto de equilibrio"},{"s":"Repartir el dinero el día que entra.","type":"Sobre del mes"},{"s":"En cuánto tiempo se paga sola una compra.","type":"Plazo de retorno"},{"s":"Atender el doble sin que cueste el doble.","type":"Escalar"},{"s":"Un servicio que hoy no cobra y algún día cobrará.","type":"Fijo aplazado"}];
const classifyTaskDB=[{"w":"El dominio del sitio","gen":"Costo","n":"Mensual","g":"Fijo","t":"No depende del volumen"},{"w":"El papel de cada ficha","gen":"Costo","n":"Por unidad","g":"Variable","t":"Sube al crecer"},{"w":"Los datos del teléfono","gen":"Costo","n":"Mensual","g":"Fijo","t":"No depende del volumen"},{"w":"El pasaje a cada taller","gen":"Costo","n":"Por unidad","g":"Variable","t":"Sube al crecer"},{"w":"La factura del dominio","gen":"Visibilidad","n":"Con recibo","g":"Se ve","t":"Alguien lo cobró"},{"w":"Las horas de revisión","gen":"Visibilidad","n":"Sin recibo","g":"No se ve","t":"Nadie lo factura"},{"w":"La cuota de 150 por aula","gen":"Flujo","n":"Entra","g":"Ingreso","t":"Suma al mes"},{"w":"La reserva de impresión","gen":"Flujo","n":"Sale","g":"Costo","t":"Resta al mes"},{"w":"Una misión publicada","gen":"Crecimiento","n":"Sin más horas","g":"Escala","t":"Sirve para todos"},{"w":"Un taller presencial","gen":"Crecimiento","n":"Con más horas","g":"No escala","t":"Se paga con tiempo"}];
const completeTaskDB=[{"s":"El costo que se paga aunque no pase nada es el costo ___.","opts":["fijo","variable","medio"],"ans":"fijo"},{"s":"El costo que sube con cada unidad es el costo ___.","opts":["variable","fijo","total"],"ans":"variable"},{"s":"Precio menos costo por unidad es el ___.","opts":["margen","ingreso","ahorro"],"ans":"margen"},{"s":"Fijos entre margen da el punto de ___.","opts":["equilibrio","venta","partida"],"ans":"equilibrio"},{"s":"Lo que se deja de hacer por otra cosa es costo de ___.","opts":["oportunidad","traslado","produccion"],"ans":"oportunidad"},{"s":"El dinero se reparte en ___ el día que entra.","opts":["sobres","cuentas","partes"],"ans":"sobres"},{"s":"Lo gratis se anota con su ___ entre paréntesis.","opts":["precio","nombre","plazo"],"ans":"precio"},{"s":"Los talleres no ___, porque se pagan con horas.","opts":["escalan","cuestan","sirven"],"ans":"escalan"}];
const explainQuestions=[{"q":"Explica la diferencia entre costo fijo y costo variable con ejemplos de M.E.T.A.S, y di qué decide cada uno.","ans":"El costo fijo se paga igual haya trabajo o no: el dominio, los datos del teléfono, la reserva de impresión, unos 750 lempiras al mes. No sube al atender más aulas, así que cada aula nueva lo abarata, y por eso es el que decide cuánto volumen hace falta para no perder. El costo variable sube con cada unidad: el papel y la tinta de cada ficha, el pasaje de cada taller, el refrigerio por participante. Crecer no lo abarata, lo multiplica, y por eso es el que decide si el precio de una unidad deja algo. Resumido: el fijo se cubre con volumen y el variable con precio."},{"q":"¿Por qué se le pone precio a la hora si nadie la paga? Da un ejemplo del proyecto.","ans":"Porque si la hora vale cero, todo parece rentable y ninguna decisión se puede comparar. Ponerle precio no significa cobrarla: significa poder elegir entre dos usos de la misma tarde. Con la hora a 100 lempiras, hacer treinta fichas a mano (una tarde entera, unas cuatro horas, 400 lempiras) y pasar esa misma tarde escribiendo una herramienta que las revise sola dejan de ser cuestión de gusto y pasan a ser una comparación con resultado. Es también el motivo de que las herramientas de _dev sean una decisión económica y no solo técnica."},{"q":"Calcula el punto de equilibrio de la cuota por aula y explica por qué no son cinco aulas.","ans":"Los fijos del mes son 750 lempiras y la cuota por aula es de 150. Dividir 750 entre 150 da cinco, pero esa cuenta supone que atender un aula no cuesta nada. Cada aula come alrededor de media hora de acompañamiento al mes, y a 100 lempiras la hora eso son 50 por aula: el margen real es 100, no 150. El punto de equilibrio es 750 entre 100, es decir ocho aulas. La lección es que el equilibrio se calcula con el margen y nunca con el precio."},{"q":"¿Cómo se anota en el presupuesto un servicio que hoy es gratis, y por qué?","ans":"Se anota igual que los demás fijos, con su precio de mercado entre paréntesis. Gratis no es un precio: es un precio aplazado. Hoy el sitio y la base de datos están en planes gratuitos, así que el fijo de infraestructura es casi cero, pero el día que haya que pagarlos el fijo mensual sube y el punto de equilibrio sube con él, de golpe y sin aviso. Si estaba anotado, ese día ya se sabe cuántas aulas hacen falta y no hay que decidir con prisa; si no estaba, se decide mal y con la factura encima."},{"q":"Un taller deja 6.400 lempiras con 900 de gastos y catorce horas de trabajo. ¿Cuánto deja de verdad y qué enseña?","ans":"Entran 6.400 y se van 900 en pasajes, refrigerio y copias, así que quedan 5.500. Pero hay catorce horas metidas, seis del taller y ocho de preparación, que a 100 lempiras la hora son 1.400. El margen real es 4.100, que sigue siendo bueno pero es la mitad de lo que parecía a simple vista. Lo que enseña: los talleres son el ingreso más rápido y el que peor escala, porque se pagan con horas que no se pueden repetir. Sirven para financiar lo que sí escala, como las fichas y las misiones, y no al revés."},{"q":"Explica el método de los sobres y por qué la regla más importante es no sacar de los fijos.","ans":"El dinero se reparte el día que entra en cuatro sobres: fijos, variables, ahorro y reinversión. Se hace así porque un sobre vacío es una respuesta clara, mientras que una cuenta con saldo siempre parece que alcanza para una cosa más. La regla de no tocar los fijos existe porque sacar de ahí para reinvertir se siente inteligente y es exactamente lo que apaga el dominio en marzo. Un proyecto familiar no cierra de golpe: se muere por goteo, un mes que no alcanzó y se pagó de la casa, y al tercero ya nadie sabe cuánto costaba ni cuánto entraba."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

