const evalTFBank=[{"q":"El costo fijo sube con cada unidad entregada.","a":false},{"q":"El costo fijo se paga aunque no se atienda ninguna aula.","a":true},{"q":"El papel de cada ficha es un costo variable.","a":true},{"q":"El punto de equilibrio se calcula dividiendo los fijos entre el precio.","a":false},{"q":"El punto de equilibrio se calcula dividiendo los fijos entre el margen.","a":true},{"q":"Ponerle precio a la hora obliga a cobrarla.","a":false},{"q":"El costo de oportunidad no aparece en ningún recibo.","a":true},{"q":"Un servicio gratuito no se anota en el presupuesto.","a":false},{"q":"De los fijos se puede sacar para reinvertir si hay una buena oportunidad.","a":false},{"q":"Los talleres se pagan con horas que no se pueden repetir.","a":true},{"q":"Una misión publicada escala mejor que una capacitación presencial.","a":true},{"q":"Regalar algo sin saber cuánto cuesta es una cuenta que llega después.","a":true},{"q":"Una inversión se juzga solo por lo que ahorra en cada unidad.","a":false},{"q":"El margen es el precio de venta de una unidad.","a":false},{"q":"En el presupuesto de esta casa la hora se valora en 100 lempiras.","a":true}];
