function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Se propone cobrar 150 lempiras al mes por aula. Los fijos del mes son 750 y cada aula come media hora de acompañamiento, con la hora valorada en 100."},{"txt":"Comprar una impresora de 4.500 lempiras ahorraría unos 2 lempiras por ficha frente a mandarlas a imprimir fuera. Hoy se imprimen unas cuarenta fichas al mes."},{"txt":"Una maestra pide treinta fichas impresas. La cuenta rápida dice «papel y tinta». La ficha tiene diez páginas y la revisión final toma veinte minutos."},{"txt":"Un taller para ocho maestros a 800 lempiras cada uno. Se gastan 900 en pasajes, refrigerio y copias, y se meten seis horas de taller más ocho de preparación."},{"txt":"Se propone poner anuncios en el APK para tener ingresos sin cobrarle a nadie. Con el tráfico de hoy la publicidad daría unas decenas de lempiras al mes."},{"txt":"El sitio y la base de datos están hoy en planes gratuitos, así que el fijo de infraestructura del proyecto es casi cero."},{"txt":"Un negocio ofrece 8.000 lempiras por su logo en las fichas del año. El trato implicaría rediseñar portadas, mandar reportes y atender reuniones: unas quince horas."},{"txt":"El proyecto lleva cientos de horas de trabajo y ninguna aparece en ninguna cuenta, porque nadie las paga."}];
const critCaseQuestions=["1. ¿Qué costos faltan en la cuenta tal como está planteada?","2. Calcula el costo por unidad o el total real, con los números que tengas.","3. ¿Cuántas unidades hacen falta para no perder, o en cuánto tiempo se recupera?","4. Escribe en 3-4 frases qué decidirías y con qué condición."];
const critCaseGuides=["Lo que casi siempre falta son las horas, las hojas que salen mal, el traslado y lo que hoy es gratis y algún día no lo será. Un costo que no se apunta lo paga alguien, y en un proyecto familiar lo paga la casa.","La cuenta se hace con el juego de números de la casa: fijos 750 al mes, hora a 100, cuota por aula 150 con media hora de soporte, o sea margen de 100 por aula.","El equilibrio es fijos entre margen, nunca fijos entre precio. Para una compra, el plazo de retorno se compara con la vida esperada del proyecto: si tarda cinco años en pagarse, la pregunta es si va a haber cinco años.","Casi ninguna oferta se acepta o se rechaza completa: se acepta con condiciones, y la condición sale del número, no del entusiasmo."];

const critErrorBank=[{"txt":"\"Cinco aulas y ya cubrimos los fijos, con eso arrancamos\".","g1":"Esa cuenta divide 750 entre 150 y supone que atender un aula no cuesta nada, cuando cada una come media hora de acompañamiento al mes.","g2":"Con el soporte contado, el margen es 100 y no 150: el equilibrio son ocho aulas. El equilibrio se calcula con el margen, nunca con el precio."},{"txt":"\"Imprimir treinta fichas sale casi gratis, es solo papel y tinta\".","g1":"Faltan las hojas que salen mal, el viaje a sacar copias y los veinte minutos de revisión de cada ficha, que a 100 la hora son 33 lempiras.","g2":"El costo por ficha ronda los 56 lempiras y el dominante es el tiempo. Por eso automatizar la revisión vale más que ahorrar en papel."},{"txt":"\"El taller dejó 5.500 lempiras limpios\".","g1":"Limpios de gastos en efectivo, sí, pero no de horas: seis de taller y ocho de preparación son catorce, o sea 1.400 lempiras.","g2":"El margen real es 4.100. Sigue siendo bueno, y aun así conviene saber que es la mitad de lo que parecía, porque con eso se compara contra otras formas de usar el mismo sábado."},{"txt":"\"El hospedaje es gratis, así que ahí no hay nada que presupuestar\".","g1":"Gratis no es un precio, es un precio aplazado. El día que empiece a cobrarse, el fijo mensual sube y el punto de equilibrio sube con él.","g2":"Se anota como fijo con su precio de mercado entre paréntesis, para que ese día ya se sepa cuántas aulas hacen falta y no haya que decidir con prisa."},{"txt":"\"Con los 8.000 del patrocinio cubrimos casi un año de dominio\".","g1":"El ingreso no es 8.000 si obliga a quince horas de trabajo: a 100 la hora eso son 1.500, así que quedan 6.500.","g2":"Y llega una sola vez. La pregunta correcta no es cuánto dan, es cuánto queda por hora invertida, y con eso se comparan ofertas que parecían muy distintas."},{"txt":"\"Sacamos del sobre de fijos para comprar el equipo, después reponemos\".","g1":"De los fijos no se saca nunca: es lo que apaga el dominio en marzo y deja el sitio caído sin que nadie lo haya decidido.","g2":"El equipo sale del sobre de reinversión, y solo con lo que haya sobrado después de apartar fijos, variables y ahorro."}];

const critDecisionBank=["Cuota de 150 por aula con fijos de 750 y media hora de soporte por aula: ¿cuántas aulas hacen falta para no perder?","Impresora de 4.500 que ahorra 2 por ficha, con cuarenta fichas al mes: ¿conviene comprarla y con qué condición?","Treinta fichas impresas «de regalo»: ¿cuánto cuestan de verdad y qué se responde?","Taller de ocho maestros a 800 con 900 de gastos y catorce horas: ¿cuánto deja por hora y con qué se compara?","Anuncios en el APK con el tráfico de hoy: ¿cubren siquiera el dominio, y qué cuestan además del dinero?","Hospedaje y base de datos hoy gratis: ¿cómo se anotan en el presupuesto y por qué?","Patrocinio de 8.000 que obliga a quince horas de trabajo: ¿cuánto queda por hora invertida?","Cientos de horas del proyecto sin precio: ¿qué número se elige y para qué sirve tenerlo?"];
const critDecisionGuide="La decisión correcta sigue los principios de la casa: se identifica quién firma, quién traba y quién paga antes de responder; se empieza pequeño y reversible; nunca se compromete a terceros que no firmaron; la autoría y el uso se acuerdan antes de entregar, no después; y todo queda por escrito con la institución y no con la persona. Cuando la oferta es grande y urgente, esa combinación es justamente la señal para tomarse los días que hagan falta y responder con una condición concreta.";

const critCompareBank=[{"a":"Pasar una tarde escribiendo la herramienta que revisa las fichas sola.","b":"Pasar esa misma tarde revisando treinta fichas a mano.","ga":"Caso A: cuesta cuatro horas una vez y baja el costo por unidad de todas las fichas que vengan después.","gb":"Caso B: cuesta las mismas cuatro horas y hay que volver a pagarlas la próxima vez que haya treinta fichas."},{"a":"Cobrar 150 por aula sabiendo que el equilibrio son ocho aulas.","b":"Cobrar 150 por aula creyendo que el equilibrio son cinco.","ga":"Caso A: se sabe a partir de qué aula deja de ser trabajo regalado y se puede decidir cuándo parar de crecer.","gb":"Caso B: se anuncia la cuota, llegan seis aulas y el mes sigue saliendo del bolsillo de la casa sin que nadie entienda por qué."},{"a":"Un taller de 4.100 de margen real un sábado.","b":"Cuatro aulas nuevas a 100 de margen cada mes.","ga":"Caso A: entra rápido y no vuelve; sirve para financiar lo que sí se repite.","gb":"Caso B: entra despacio y vuelve solo todos los meses, y no cuesta un sábado cada vez."},{"a":"Anotar el hospedaje gratis con su precio entre paréntesis.","b":"Dejarlo fuera del presupuesto porque hoy no cuesta.","ga":"Caso A: el día de la factura ya se sabe cuántas aulas hacen falta y no hay decisión con prisa.","gb":"Caso B: el fijo sube de golpe, el equilibrio se mueve y hay que decidir con la factura encima."}];

const critCauseBank=[{"cause":"Se calcula el equilibrio dividiendo los fijos entre el precio.","guide":"Sale un número más bonito y más falso: el equilibrio se calcula con el margen, que es el precio menos lo que cuesta atender esa unidad."},{"cause":"No se le pone precio a la hora del que hace el trabajo.","guide":"Todo parece rentable y ninguna decisión se puede comparar. La hora es el gasto más grande del proyecto y el único invisible."},{"cause":"Se deja fuera del presupuesto lo que hoy es gratis.","guide":"El día que empiece a cobrarse, el fijo sube y el equilibrio se mueve de golpe, justo cuando hay menos margen para reaccionar."},{"cause":"Se saca del sobre de fijos para una compra.","guide":"Se siente inteligente y es lo que apaga el dominio en marzo. De los fijos no se saca nunca."},{"cause":"Se acepta un ingreso sin contar las horas que obliga.","guide":"El ingreso real baja y se compara mal con otras ofertas. La pregunta es cuánto queda por hora invertida."},{"cause":"Se crece con servicios que no escalan.","guide":"Cada cliente nuevo cuesta las mismas horas que el anterior, así que el trabajo crece igual que el ingreso y el proyecto se atasca en una persona."}];
const critEffectBank=[{"effect":"Con nueve aulas el mes dejó de salir del bolsillo de la casa.","guide":"El equilibrio estaba bien calculado, con el margen y no con el precio, así que el número sirvió para saber cuándo parar de preocuparse."},{"effect":"La herramienta de revisión bajó el costo de cada ficha a la mitad.","guide":"Se cambió tiempo por unidad por tiempo una sola vez. Es la única forma de crecer sin que crezcan las horas."},{"effect":"Llegó la factura del hospedaje y ya estaba prevista.","guide":"Estaba anotado como fijo con su precio entre paréntesis, así que no hubo que decidir con prisa ni recortar de donde no se debe."},{"effect":"Se dijo que no a un patrocinio que parecía muy bueno.","guide":"Al calcular lo que quedaba por hora invertida, la oferta bajaba de categoría. El número decidió, no el entusiasmo."},{"effect":"El sobre de fijos llegó completo a fin de año.","guide":"Nunca se sacó de ahí. Es la regla más aburrida del método y la que evita la muerte por goteo."},{"effect":"Se cobró por el taller sabiendo exactamente cuánto dejaba por hora.","guide":"Con ese dato se pudo comparar contra otras formas de usar el mismo sábado, que es justo para lo que sirve el precio de la hora."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 La cuenta sobre la mesa · Forma ${cf} · El presupuesto real · Ruta del Poder`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. Simulacro de Presión: la interpelación <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿El presupuesto real, qué se pide a cambio y con qué condición por escrito aceptarías? Explica por qué tu salida es mejor que aceptar completo o que rechazar de plano.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 La cuenta sobre la mesa: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. Simulacro de Presión: la interpelación</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿El presupuesto real, qué se pide a cambio y con qué condición por escrito aceptarías? Explica por qué tu salida es mejor que aceptar completo o que rechazar de plano.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>La cuenta sobre la mesa El presupuesto real · Ruta del Poder · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · La cuenta sobre la mesa · El presupuesto real · Ruta del Poder · Etapa 2 · Poder Económico</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: La cuenta sobre la mesa · El presupuesto real · Ruta del Poder · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

