const timelineData=[{"y":"1","icon":"💵","label":"El ingreso","text":"Lo que entra, y de dónde. <strong>Se mide:</strong> por mes y por origen. <strong>Se esconde:</strong> cuando se cuenta un ingreso único como si volviera cada mes. <strong>En M.E.T.A.S:</strong> cuota por aula (vuelve) contra taller o patrocinio (no vuelven)."},{"y":"2","icon":"🏠","label":"El costo fijo","text":"Lo que se paga <strong>aunque no pase nada</strong>. <strong>Se mide:</strong> sumando el mes completo. <strong>Se esconde:</strong> en lo que hoy es gratis. <strong>En M.E.T.A.S:</strong> unos 750 al mes entre dominio, datos y reserva de impresión."},{"y":"3","icon":"📄","label":"El costo variable","text":"Lo que sube <strong>con cada unidad</strong>. <strong>Se mide:</strong> por unidad, no por mes. <strong>Se esconde:</strong> en las hojas que salen mal y en el traslado. <strong>En M.E.T.A.S:</strong> unos 20 de papel y tinta por ficha de diez páginas."},{"y":"4","icon":"⏳","label":"El costo de la hora","text":"El precio del <strong>propio tiempo</strong>. <strong>Se mide:</strong> eligiendo un número y usándolo siempre. <strong>Se esconde:</strong> en todas partes, porque nadie lo factura. <strong>En M.E.T.A.S:</strong> 100 lempiras la hora."},{"y":"5","icon":"🧮","label":"El costo por unidad","text":"Variables <strong>más horas</strong>, por cada cosa entregada. <strong>Se mide:</strong> con cronómetro, una vez. <strong>Se esconde:</strong> cuando solo se cuenta lo que se pagó en efectivo. <strong>En M.E.T.A.S:</strong> una ficha impresa cuesta unos 56, no 20."},{"y":"6","icon":"📈","label":"El margen","text":"Precio <strong>menos</strong> costo por unidad. <strong>Se mide:</strong> por unidad vendida. <strong>Se esconde:</strong> cuando se confunde con el precio. <strong>En M.E.T.A.S:</strong> un aula a 150 con media hora de soporte deja 100."},{"y":"7","icon":"⚖️","label":"El punto de equilibrio","text":"Fijos <strong>entre</strong> margen. <strong>Se mide:</strong> en unidades, no en dinero. <strong>Se esconde:</strong> cuando se divide entre el precio y sale más bajo de lo real. <strong>En M.E.T.A.S:</strong> 750 entre 100 son ocho aulas."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

