const parteData={"fijos":{"nombre":"Los costos fijos","icon":"🏠","estructura":{"title":"Qué es","info":"• Lo que se paga <strong>aunque no pase nada</strong><br>• No sube al atender más aulas ni al imprimir más fichas<br>• Cada unidad nueva lo abarata, y por eso el volumen lo cubre"},"funcion":{"title":"Cómo se calcula","info":"• Se listan todos los pagos del mes, uno por uno<br>• Se incluye <strong>lo que hoy es gratis</strong>, con su precio entre paréntesis<br>• Se suma y ese número no se vuelve a discutir cada mes"},"enfermedades":{"title":"Dónde se esconde","info":"• En los planes gratuitos de hospedaje y base de datos<br>• En los datos del teléfono, que se pagan igual y nadie apunta<br>• En la reserva de impresión, que se gasta sin registrarse"},"cuidados":{"title":"Los números de M.E.T.A.S","info":"• Dominio: unos <strong>250 al mes</strong><br>• Datos del teléfono: unos <strong>350</strong><br>• Reserva de impresión: unos <strong>150</strong><br>• Total: <strong>750 lempiras al mes</strong>"}},"variables":{"nombre":"Los costos variables","icon":"📄","estructura":{"title":"Qué es","info":"• Lo que sube <strong>con cada unidad</strong> entregada<br>• Crecer no lo abarata: lo multiplica<br>• Es el que decide si el precio de una unidad deja algo"},"funcion":{"title":"Cómo se calcula","info":"• Se mide sobre <strong>una sola unidad</strong>, no sobre el mes<br>• Se incluye lo que sale mal, estimado por arriba<br>• Se incluye el traslado, que casi nunca se apunta"},"enfermedades":{"title":"Dónde se esconde","info":"• En las hojas que se imprimieron torcidas<br>• En el viaje a sacar copias, que cuesta pasaje y una hora<br>• En el refrigerio y los materiales de cada taller"},"cuidados":{"title":"Los números de M.E.T.A.S","info":"• Ficha de diez páginas: unos <strong>20 de papel y tinta</strong><br>• Hojas malas y traslado: unos <strong>3 más</strong> por ficha<br>• Taller: unos <strong>900</strong> entre pasajes, refrigerio y copias"}},"hora":{"nombre":"El costo de la hora","icon":"⏳","estructura":{"title":"Qué es","info":"• El precio que se le pone al <strong>propio tiempo</strong><br>• No significa cobrarlo: significa poder comparar<br>• Es el gasto más grande del proyecto y el único invisible"},"funcion":{"title":"Cómo se calcula","info":"• Se elige <strong>un número y se usa siempre</strong>, aunque incomode<br>• Se apuntan las horas reales durante dos semanas<br>• Se multiplican horas por precio, y ya es un costo como otro"},"enfermedades":{"title":"Dónde se esconde","info":"• En «total, lo hago yo»<br>• En las tardes de soporte que no se apuntan en ningún lado<br>• En el costo de oportunidad: lo que no se hizo por hacer esto"},"cuidados":{"title":"Los números de M.E.T.A.S","info":"• Precio de la hora: <strong>100 lempiras</strong><br>• Revisión de una ficha: 20 minutos = <strong>33</strong><br>• Soporte por aula: media hora al mes = <strong>50</strong><br>• Preparar un taller: 8 horas = <strong>800</strong>"}},"equilibrio":{"nombre":"El punto de equilibrio","icon":"⚖️","estructura":{"title":"Qué es","info":"• <strong>Cuántas unidades</strong> hacen falta para no perder<br>• Se dice en aulas, fichas o talleres, nunca en dinero<br>• Es la única cifra que hay que saber de memoria"},"funcion":{"title":"Cómo se calcula","info":"• Fijos <strong>entre margen</strong>, nunca entre precio<br>• El margen es el precio menos lo que cuesta atender esa unidad<br>• Si el resultado no es entero, se redondea hacia arriba"},"enfermedades":{"title":"Dónde se esconde","info":"• Cuando se divide entre el precio y sale un número más bonito<br>• Cuando sube sin avisar porque empezó a cobrarse algo gratis<br>• Cuando se promete un servicio nuevo que come horas de todos"},"cuidados":{"title":"Los números de M.E.T.A.S","info":"• Fijos: <strong>750</strong> · Cuota por aula: <strong>150</strong><br>• Soporte por aula: media hora = <strong>50</strong><br>• Margen por aula: <strong>100</strong><br>• Equilibrio: 750 / 100 = <strong>8 aulas</strong>"}}};
let labParte='fijos',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente gestor en formación!','¡Sabes por dónde se mueve esto!','¡Estratega institucional!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🧾 ¡'+name+' completó la Etapa 2 de la Ruta del Poder (El presupuesto real)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

// ===================== INIT =====================
window.addEventListener('DOMContentLoaded',()=>{
  initTheme();
  loadProgress();
  initTimeline();
  upFC();
  buildQz();
  showQz();
  buildClass();
  showId();
  showCmp();
  updateRetoButtons();
  buildRoute();
  showNeuron();
  showNeuro();
  showEnfer();
  updateLabDisplay();
  document.querySelector('[data-parte="fijos"]')?.classList.add('active-pri');
  document.querySelector('[data-aspecto="estructura"]')?.classList.add('active-sec');
  renderAchPanel();
});
